// Pseudo-flow wiring
async function retrieve(query) {
  const e = embed(query);
  const chunks = vectorDB.search(e, topK=5);
  const ranked = rerank(chunks, query);
  return ranked.map(c => ({id: c.id, text: c.text, source: c.source}));
}
